import{_ as r,a0 as a,w as s,s as n,I as l,x as e,a1 as o,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Suplemon：带有多光标支持的现代 CLI 文本编辑器 | LCTT x X-CMD","titleTemplate":false,"description":"Suplemon：带有多光标支持的现代 CLI 文本编辑器 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Suplemon：带有多光标支持的现代 CLI 文本编辑器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Suplemon：带有多光标支持的现代 CLI 文本编辑器 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support","title":"Suplemon：带有多光标支持的现代 CLI 文本编辑器","tag":"201712","desc":""},"relativePath":"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support.md","filePath":"[post].md"}'),u={name:"201712/20171129 Suplemon - Modern CLI Text Editor with Multi Cursor Support.md"};function h(c,t,m,g,C,b){const d=a("Link");return s(),n("div",null,[t[19]||(t[19]=l("h1",{id:"suplemon-带有多光标支持的现代-cli-文本编辑器",tabindex:"-1"},[e("Suplemon：带有多光标支持的现代 CLI 文本编辑器 "),l("a",{class:"header-anchor",href:"#suplemon-带有多光标支持的现代-cli-文本编辑器","aria-label":"Permalink to “Suplemon：带有多光标支持的现代 CLI 文本编辑器”"},"​")],-1)),l("p",null,[t[1]||(t[1]=e("Suplemon 是一个 CLI 中的现代文本编辑器，它模拟 ",-1)),o(d,{href:"https://linoxide.com/tools/install-sublime-text-editor-linux/"},{default:i(()=>[...t[0]||(t[0]=[e("Sublime Text",-1)])]),_:1}),t[2]||(t[2]=e(" 的多光标行为和其它特性。它是轻量级的，非常易于使用，就像 Nano 一样。",-1))]),t[20]||(t[20]=l("p",null,"使用 CLI 编辑器的好处之一是，无论你使用的 Linux 发行版是否有 GUI，你都可以使用它。这种文本编辑器也很简单、快速和强大。",-1)),l("p",null,[t[4]||(t[4]=e("你可以在其",-1)),o(d,{href:"https://github.com/richrd/suplemon/"},{default:i(()=>[...t[3]||(t[3]=[e("官方仓库",-1)])]),_:1}),t[5]||(t[5]=e("中找到有用的信息和源代码。",-1))]),t[21]||(t[21]=p('<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>这些是一些它有趣的功能：</p><ul><li>多光标支持</li><li>撤销/重做</li><li>复制和粘贴，带有多行支持</li><li>鼠标支持</li><li>扩展</li><li>查找、查找所有、查找下一个</li><li>语法高亮</li><li>自动完成</li><li>自定义键盘快捷键</li></ul><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>首先，确保安装了最新版本的 python3 和 pip3。</p><p>然后在终端输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip3 install suplemon</span></span></code></pre></div><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><h4 id="在当前目录中创建一个新文件" tabindex="-1">在当前目录中创建一个新文件 <a class="header-anchor" href="#在当前目录中创建一个新文件" aria-label="Permalink to “在当前目录中创建一个新文件”">​</a></h4><p>打开一个终端并输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon</span></span></code></pre></div><p>你将看到如下：</p><p><img src="https://linoxide.com/wp-content/uploads/2017/11/suplemon-new-file.png" alt="suplemon new file"></p><h4 id="打开一个或多个文件" tabindex="-1">打开一个或多个文件 <a class="header-anchor" href="#打开一个或多个文件" aria-label="Permalink to “打开一个或多个文件”">​</a></h4><p>打开一个终端并输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon &lt;filename1&gt; &lt;filename2&gt; ... &lt;filenameN&gt;</span></span></code></pre></div><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ suplemon example1.c example2.c</span></span></code></pre></div><h3 id="主要配置" tabindex="-1">主要配置 <a class="header-anchor" href="#主要配置" aria-label="Permalink to “主要配置”">​</a></h3><p>你可以在 <code>~/.config/suplemon/suplemon-config.json</code> 找到配置文件。</p><p>编辑这个文件很简单，你只需要进入命令模式（进入 suplemon 后）并运行 <code>config</code> 命令。你可以通过运行 <code>config defaults</code> 来查看默认配置。</p><h4 id="键盘映射配置" tabindex="-1">键盘映射配置 <a class="header-anchor" href="#键盘映射配置" aria-label="Permalink to “键盘映射配置”">​</a></h4><p>我会展示 suplemon 的默认键映射。如果你想编辑它们，只需运行 <code>keymap</code> 命令。运行 <code>keymap default</code> 来查看默认的键盘映射文件。</p><div class="table-wrap"><table><thead><tr><th>操作</th><th>快捷键</th></tr></thead><tbody><tr><td>退出</td><td><code>Ctrl + Q</code></td></tr><tr><td>复制行到缓冲区</td><td><code>Ctrl + C</code></td></tr><tr><td>剪切行缓冲区</td><td><code>Ctrl + X</code></td></tr><tr><td>插入缓冲区</td><td><code>Ctrl + V</code></td></tr><tr><td>复制行</td><td><code>Ctrl + K</code></td></tr><tr><td>跳转</td><td><code>Ctrl + G</code>。 你可以跳转到一行或一个文件（只需键入一个文件名的开头）。另外，可以输入类似于 <code>exam:50</code> 跳转到 <code>example.c</code> 第 <code>50</code> 行。</td></tr><tr><td>用字符串或正则表达式搜索</td><td><code>Ctrl + F</code></td></tr><tr><td>搜索下一个</td><td><code>Ctrl + D</code></td></tr><tr><td>去除空格</td><td><code>Ctrl + T</code></td></tr><tr><td>在箭头方向添加新的光标</td><td><code>Alt + 方向键</code></td></tr><tr><td>跳转到上一个或下一个单词或行</td><td><code>Ctrl + 左/右</code></td></tr><tr><td>恢复到单光标/取消输入提示</td><td><code>Esc</code></td></tr><tr><td>向上/向下移动行</td><td><code>Page Up</code> / <code>Page Down</code></td></tr><tr><td>保存文件</td><td><code>Ctrl + S</code></td></tr><tr><td>用新名称保存文件</td><td><code>F1</code></td></tr><tr><td>重新载入当前文件</td><td><code>F2</code></td></tr><tr><td>打开文件</td><td><code>Ctrl + O</code></td></tr><tr><td>关闭文件</td><td><code>Ctrl + W</code></td></tr><tr><td>切换到下一个/上一个文件</td><td><code>Ctrl + Page Up</code> / <code>Ctrl + Page Down</code></td></tr><tr><td>运行一个命令</td><td><code>Ctrl + E</code></td></tr><tr><td>撤消</td><td><code>Ctrl + Z</code></td></tr><tr><td>重做</td><td><code>Ctrl + Y</code></td></tr><tr><td>触发可见的空格</td><td><code>F7</code></td></tr><tr><td>切换鼠标模式</td><td><code>F8</code></td></tr><tr><td>显示行号</td><td><code>F9</code></td></tr><tr><td>显示全屏</td><td><code>F11</code></td></tr></tbody></table></div><h4 id="鼠标快捷键" tabindex="-1">鼠标快捷键 <a class="header-anchor" href="#鼠标快捷键" aria-label="Permalink to “鼠标快捷键”">​</a></h4><ul><li>将光标置于指针位置：左键单击</li><li>在指针位置添加一个光标：右键单击</li><li>垂直滚动：向上/向下滚动滚轮</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在尝试 Suplemon 一段时间后，我改变了对 CLI 文本编辑器的看法。我以前曾经尝试过 Nano，是的，我喜欢它的简单性，但是它的现代特征的缺乏使它在日常使用中变得不实用。</p><p>这个工具有 CLI 和 GUI 世界最好的东西……简单性和功能丰富！所以我建议你试试看，并在评论中写下你的想法 😃</p><hr>',30)),l("p",null,[t[7]||(t[7]=e("via: ",-1)),o(d,{href:"https://linoxide.com/tools/suplemon-cli-text-editor-multi-cursor/"},{default:i(()=>[...t[6]||(t[6]=[e("https://linoxide.com/tools/suplemon-cli-text-editor-multi-cursor/",-1)])]),_:1})]),l("p",null,[t[11]||(t[11]=e("作者：",-1)),o(d,{href:"https://linoxide.com/author/ursinov/"},{default:i(()=>[...t[8]||(t[8]=[e("Ivo Ursino",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),o(d,{href:"https://github.com/geekpi"},{default:i(()=>[...t[9]||(t[9]=[e("geekpi",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),o(d,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),o(d,{href:"https://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const T=r(u,[["render",h]]);export{x as __pageData,T as default};
